import java.nio.file.*;import java.util.*;import ru.bccontrol.sedonastudio.storage.*;import ru.bccontrol.sedonastudio.model.*;
public class ViewStateTests {
 static void check(boolean value,String why){if(!value)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{Path root=Files.createTempDirectory("studio-view-");Project p=new Project();p.name="One";Project.Node f=new Project.Node();f.id="folder";f.name="group";f.type="sys::Folder";p.nodes.put(f.id,f);ViewStateStore.State s=new ViewStateStore.State(ViewStateStore.projectKey(p),f.id,ViewStateStore.lineage(p,f.id),.75,.22,.31,.25,.73,.68,1,2);Path a=root.resolve("a/workspace.json"),b=root.resolve("b/workspace.json");ViewStateStore.save(s,a);check(ViewStateStore.load(a).orElseThrow().equals(s),"Roundtrip");check(ViewStateStore.load(b).isEmpty(),"Session isolation");check(ViewStateStore.restoreFolder(s,p).equals(f.id),"Folder restoration");p.nodes.get(f.id).name="different";check(ViewStateStore.restoreFolder(s,p).equals("0"),"Reused folder ID rejected");p.nodes.get(f.id).name="group";p.name="Other";check(ViewStateStore.restoreFolder(s,p).equals("0"),"Other project rejected");
  String original=Files.readString(a);Files.writeString(a,original.replace("0.75","99.0"));boolean invalid=false;try{ViewStateStore.load(a);}catch(java.io.IOException expected){invalid=true;}check(invalid,"Invalid zoom rejected");Files.writeString(a,"{bad");invalid=false;try{ViewStateStore.load(a);}catch(java.io.IOException expected){invalid=true;}check(invalid,"Corrupt view rejected");check(Files.readString(a).equals("{bad"),"Read preserves damaged view");System.out.println("PASS view state: atomic roundtrip, per-session isolation, project/folder identity, range validation and corrupt-file preservation");}
}
